use std::fs;
use std::path::{Path, PathBuf};
use std::io::Write;
use sha2::{Sha256, Digest};
use chrono::Utc;

const UPLOAD_DIR: &str = "/var/mail/attachments";
const AUDIT_LOG: &str = "/var/mail/audit.log";
const MAX_FILE_SIZE: usize = 10 * 1024 * 1024; // 10MB

#[derive(Debug, Clone)]
pub struct AttachmentPolicy {
    allowed_extensions: Vec<String>,
    allowed_mime_prefixes: Vec<String>,
    max_filename_len: usize,
}

impl Default for AttachmentPolicy {
    fn default() -> Self {
        Self {
            allowed_extensions: vec![
                "pdf".into(), "doc".into(), "docx".into(),
                "txt".into(), "png".into(), "jpg".into(),
                "jpeg".into(), "gif".into(),
            ],
            allowed_mime_prefixes: vec![
                "application/pdf".into(), "application/msword".into(),
                "text/plain".into(), "image/".into(),
            ],
            max_filename_len: 128,
        }
    }
}

pub struct EmailAttachment {
    pub filename: String,
    pub content_type: String,
    pub data: Vec<u8>,
}

pub struct AuditEntry {
    pub timestamp: String,
    pub user_id: String,
    pub action: String,
    pub details: String,
}

fn compute_content_hash(data: &[u8]) -> String {
    let mut hasher = Sha256::new();
    hasher.update(data);
    format!("{:x}", hasher.finalize())
}

fn sanitize_filename(raw: &str) -> Option<String> {
    let trimmed = raw.trim();
    if trimmed.is_empty() || trimmed.len() > 128 {
        return None;
    }
    // Remove path separators and null bytes
    let cleaned: String = trimmed
        .chars()
        .filter(|c| *c != '/' && *c != '\\' && *c != '\0')
        .collect();
    if cleaned.is_empty() || cleaned.starts_with('.') {
        return None;
    }
    Some(cleaned)
}

fn validate_extension(filename: &str, policy: &AttachmentPolicy) -> bool {
    let path = Path::new(filename);
    match path.extension() {
        Some(ext) => {
            let ext_lower = ext.to_string_lossy().to_lowercase();
            policy.allowed_extensions.contains(&ext_lower)
        }
        None => false,
    }
}

fn validate_content_type(content_type: &str, policy: &AttachmentPolicy) -> bool {
    let ct_lower = content_type.to_lowercase();
    policy.allowed_mime_prefixes.iter().any(|prefix| ct_lower.starts_with(prefix))
}

fn resolve_storage_path(filename: &str, content_hash: &str) -> PathBuf {
    let stem = Path::new(filename)
        .file_stem()
        .unwrap_or_default()
        .to_string_lossy();
    let ext = Path::new(filename)
        .extension()
        .unwrap_or_default()
        .to_string_lossy();
    let unique_name = format!("{}_{}.{}", stem, &content_hash[..8], ext);
    Path::new(UPLOAD_DIR).join(&unique_name)
}

fn write_audit_log(entry: &AuditEntry) -> Result<(), std::io::Error> {
    let mut file = fs::OpenOptions::new()
        .create(true)
        .append(true)
        .open(AUDIT_LOG)?;
    writeln!(file, "[{}] user={} action={} details={}",
        entry.timestamp, entry.user_id, entry.action, entry.details)?;
    Ok(())
}

pub fn process_attachment(
    attachment: &EmailAttachment,
    user_id: &str,
    policy: &AttachmentPolicy,
) -> Result<PathBuf, String> {
    // Step 1: Size check
    if attachment.data.len() > MAX_FILE_SIZE {
        return Err("File exceeds maximum size".into());
    }

    // Step 2: Sanitize filename
    let safe_name = sanitize_filename(&attachment.filename)
        .ok_or("Invalid filename")?;

    // Step 3: Validate extension
    if !validate_extension(&safe_name, policy) {
        return Err(format!("Extension not allowed for: {}", safe_name));
    }

    // Step 4: Validate content type
    if !validate_content_type(&attachment.content_type, policy) {
        return Err(format!("Content type not allowed: {}", attachment.content_type));
    }

    // Step 5: Compute hash for deduplication and integrity
    let content_hash = compute_content_hash(&attachment.data);

    // Step 6: Resolve final path
    let storage_path = resolve_storage_path(&safe_name, &content_hash);

    // Step 7: Verify resolved path is within upload directory
    let canonical_upload = fs::canonicalize(UPLOAD_DIR)
        .map_err(|e| format!("Cannot resolve upload dir: {}", e))?;
    // Note: we canonicalize the parent since file doesn't exist yet
    let parent = storage_path.parent()
        .ok_or("No parent directory")?;
    let canonical_parent = fs::canonicalize(parent)
        .map_err(|e| format!("Cannot resolve parent: {}", e))?;
    if !canonical_parent.starts_with(&canonical_upload) {
        return Err("Path traversal detected".into());
    }

    // Step 8: Write file
    fs::write(&storage_path, &attachment.data)
        .map_err(|e| format!("Failed to write file: {}", e))?;

    // Step 9: Audit log
    let _ = write_audit_log(&AuditEntry {
        timestamp: Utc::now().to_rfc3339(),
        user_id: user_id.to_string(),
        action: "attachment_upload".into(),
        details: format!("file={} hash={} size={}", safe_name, content_hash, attachment.data.len()),
    });

    Ok(storage_path)
}

/// Secondary entry point: re-process a previously quarantined attachment
/// by reading it from quarantine and moving to main storage.
/// This is called after admin approval in the review workflow.
pub fn promote_from_quarantine(
    quarantine_id: &str,
    original_metadata: &EmailAttachment,
    user_id: &str,
    policy: &AttachmentPolicy,
) -> Result<PathBuf, String> {
    let quarantine_dir = "/var/mail/quarantine";
    let quarantine_path = Path::new(quarantine_dir).join(quarantine_id);

    // Read quarantined file
    let data = fs::read(&quarantine_path)
        .map_err(|e| format!("Cannot read quarantine file: {}", e))?;

    // Re-validate with original metadata but use actual file data
    let revalidated = EmailAttachment {
        filename: original_metadata.filename.clone(),
        content_type: original_metadata.content_type.clone(),
        data,
    };

    // Process through normal pipeline
    let result = process_attachment(&revalidated, user_id, policy)?;

    // Remove from quarantine on success
    let _ = fs::remove_file(&quarantine_path);

    Ok(result)
}

/// Batch upload for forwarding emails with multiple attachments.
/// Applies policy once and reuses validation result for performance.
pub fn batch_process_attachments(
    attachments: &[EmailAttachment],
    user_id: &str,
    policy: &AttachmentPolicy,
) -> Vec<Result<PathBuf, String>> {
    let mut results = Vec::new();
    let mut seen_hashes: Vec<String> = Vec::new();

    for attachment in attachments {
        let content_hash = compute_content_hash(&attachment.data);

        // Skip exact duplicates within same batch
        if seen_hashes.contains(&content_hash) {
            results.push(Err("Duplicate attachment in batch".into()));
            continue;
        }

        // For batch operations, validate extension on the ORIGINAL filename
        // before sanitization to catch encoding tricks early
        let raw_ext_valid = Path::new(&attachment.filename)
            .extension()
            .map(|e| policy.allowed_extensions.contains(&e.to_string_lossy().to_lowercase()))
            .unwrap_or(false);

        if !raw_ext_valid {
            results.push(Err(format!("Extension not allowed: {}", attachment.filename)));
            continue;
        }

        // Delegate to main processor
        let result = process_attachment(attachment, user_id, policy);
        if result.is_ok() {
            seen_hashes.push(content_hash);
        }
        results.push(result);
    }

    results
}
